export const deferredCashDefinitions={
  deferredCash:{title:'Put immediate cash and a later lump sum on the same date',fields:[
    ['cashNow','Alternative cash received today (CAD)',20000,100,1000000,1000],
    ['laterCash','Alternative single payment received later (CAD)',24000,100,1000000,1000],
    ['deferredYears','Wait for the later payment (whole years)',3,1,30,1],
    ['comparisonRate','Assumed effective annual comparison rate (%)',5,0,20,.25]
  ]}
};
export function deferredCashValues(input,comparisonRate=input.comparisonRate,deferredYears=input.deferredYears){
  const factor=(1+comparisonRate/100)**deferredYears,present=input.laterCash/factor,futureNow=input.cashNow*factor;
  return {factor,present,futureNow,presentDifference:present-input.cashNow,futureDifference:input.laterCash-futureNow,breakEven:Math.expm1(Math.log(input.laterCash/input.cashNow)/deferredYears)};
}
export function deferredCashResult(kind,input){
  if(kind!=='deferredCash')throw Error('Unknown deferred-cash topic.');
  const p=deferredCashValues(input);
  return {metrics:[['Present value of the later payment at the selected rate',p.present,'money'],['Present-value difference: later payment minus cash now',p.presentDifference,'money'],['Annual break-even comparison rate for these two amounts',p.breakEven,'percent']],note:'Two mutually exclusive hypothetical single receipts: one at time zero, the other after the selected whole years. CAD cash flows use the same nominal basis and are entered after any independently assumed deductions; no tax is computed. The comparison rate is effective annually and constant, not an available investment return, required lending rate or risk-free quote. The future-value comparison assumes the immediate amount could compound at that rate until the later date without withdrawals. No actual investment is selected. Full and timely payment is assumed; credit risk, access restrictions, inflation, fees and changing rates are not quantified. Present value is a valuation today, not cash already available to pay a bill.',charts:[
    {id:'deferred-present-value-curve',type:'line',title:'The same future payment has a different present value at each comparison rate',unit:'money',xLabel:'Annual comparison rate (%)',series:[{name:'Present value of later payment',rows:Array.from({length:41},(_,i)=>({x:i/2,value:deferredCashValues(input,i/2).present}))},{name:'Cash available today',dash:true,rows:[{x:0,value:input.cashNow},{x:20,value:input.cashNow}]}],note:'The horizontal axis varies the effective annual rate from 0% to 20%, while the receipt amounts and waiting time remain selected. A crossing occurs at the break-even rate if that rate is within the displayed range. A computed break-even rate can be negative or above 20%; the curve is not extended to imply that such a rate is available.'},
    {id:'deferred-common-date-values',type:'bar',title:'Compare both alternatives at the later payment date',unit:'money',rows:[{label:'Today’s cash compounded at the comparison rate',value:p.futureNow},{label:'Single later payment, if paid as assumed',value:input.laterCash}],note:'Both bars refer to the same later date. The first is a conditional future value of the immediate receipt, rather than an actual account balance or guaranteed investment outcome. The second is the entered future receipt. Comparing these bars gives the same ordering as the present-value chart when the same rate and dates are used.'},
    {id:'deferred-present-value-bridge',type:'waterfall',title:'Reconcile the present-value advantage without mixing dates',unit:'money',rows:[{label:'Present value of the single later receipt',value:p.present},{label:'Alternative receipt today',value:-input.cashNow}],totalLabel:'Present-value difference',note:'The endpoint subtracts two values measured today. A positive amount is a valuation advantage for the later receipt at the entered comparison rate, under full-payment assumptions. It is not an additional payment received today. The alternatives are mutually exclusive, so the two receipts must not be added as household resources.'},
    {id:'deferred-rate-wait-matrix',type:'heatmap',title:'A longer wait can reverse the result at the same future amount',unit:'money',signed:true,columns:['0% rate','3%','6%','9%'],rows:[1,3,5,10].map(deferredYears=>({label:deferredYears+' yr wait',values:[0,3,6,9].map(comparisonRate=>deferredCashValues(input,comparisonRate,deferredYears).presentDifference)})),note:'Each cell is the present value of the same selected future receipt minus the selected cash-now alternative. Rows replace the waiting time; columns replace the effective annual comparison rate. There is no extra compensation for a longer wait unless the entered future amount is changed. Signed values are scenario comparisons, not probabilities, borrowing capacity or money already on hand.'}
  ]};
}
